impl GradTextFill {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("stops:");
        out.push('[');
        for (i0, e0) in self.stops.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",angle_deg:");
        uo_codec::dump::f64(out, self.angle_deg);
        out.push_str(",scaled:");
        out.push_str(if self.scaled { "true" } else { "false" });
        out.push_str(",path:");
        match self.path {
            Some(v) => {
                uo_codec::dump::utf16(out, t.sym_units(v));
            }
            None => out.push('-'),
        }
        out.push_str(",fill_to:");
        match &self.fill_to {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

