        out.push_str(",stops:");
        match &self.stops {
            Some(v) => {
                out.push('[');
                for (i0, e0) in v.iter().enumerate() {
                    if i0 > 0 { out.push(','); }
                    e0.dump(out, t);
                }
                out.push(']');
            }
            None => out.push('-'),
        }
        out.push_str(",angle:");
