/// Dumps every table entry (the entries a stream of messages carried).
pub fn dump_tables(tables: &Tables) -> String {
    let t = tables;
    let mut out = String::new();
    out.push_str("sym=[");
    for (i, e) in t.sym.iter().enumerate() {
        if i > 0 { out.push(','); }
        uo_codec::dump::utf16(&mut out, e);
    }
    out.push_str("];");
    out.push_str("faces=[");
    for (i, e) in t.faces.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("images=[");
    for (i, e) in t.images.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("text_fx=[");
    for (i, e) in t.text_fx.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("page_fills=[");
    for (i, e) in t.page_fills.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("cust=[");
    for (i, e) in t.cust.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out
}

/// The new entries of one message (`first`: at least one per table, so ids can refer to something), and the bounds the body may use.
pub fn random_delta(rng: &mut Rng, tables: &Tables, generation: u32, first: bool) -> (Delta, Bounds) {
    let mut d = Delta { generation, ..Delta::default() };
    let mut b = Bounds::default();
    let from_sym = u32::try_from(tables.sym.len()).unwrap_or(0);
    let count_sym = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.sym.from = from_sym;
    b.sym = from_sym + count_sym;
    let from_faces = u32::try_from(tables.faces.len()).unwrap_or(0);
    let count_faces = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.faces.from = from_faces;
    b.faces = from_faces + count_faces;
    let from_images = u32::try_from(tables.images.len()).unwrap_or(0);
    let count_images = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.images.from = from_images;
    b.images = from_images + count_images;
    let from_text_fx = u32::try_from(tables.text_fx.len()).unwrap_or(0);
    let count_text_fx = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.text_fx.from = from_text_fx;
    b.text_fx = from_text_fx + count_text_fx;
    let from_page_fills = u32::try_from(tables.page_fills.len()).unwrap_or(0);
    let count_page_fills = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.page_fills.from = from_page_fills;
    b.page_fills = from_page_fills + count_page_fills;
    let from_cust = u32::try_from(tables.cust.len()).unwrap_or(0);
    let count_cust = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.cust.from = from_cust;
    b.cust = from_cust + count_cust;
    for i in 0..count_sym { d.sym.items.push(rng.unique_utf16(from_sym + i, 4)); }
    for _ in 0..count_faces { d.faces.items.push(Face::random(rng, &b, 1)); }
    for _ in 0..count_images { d.images.items.push(Image::random(rng, &b, 1)); }
    for _ in 0..count_text_fx { d.text_fx.items.push(TextFx::random(rng, &b, 1)); }
    for _ in 0..count_page_fills { d.page_fills.items.push(PageFill::random(rng, &b, 1)); }
    for _ in 0..count_cust { d.cust.items.push(CustGeom::random(rng, &b, 1)); }
    (d, b)
}

/// Appends the entries of `delta` to `tables` (what the decoder does), so a following delta starts after them.
pub fn apply_delta(tables: &mut Tables, delta: &Delta) {
    if tables.generation != Some(delta.generation) { tables.clear(); tables.generation = Some(delta.generation); }
    tables.sym.extend(delta.sym.items.iter().cloned());
    tables.faces.extend(delta.faces.items.iter().cloned());
    tables.images.extend(delta.images.items.iter().cloned());
    tables.text_fx.extend(delta.text_fx.items.iter().cloned());
    tables.page_fills.extend(delta.page_fills.items.iter().cloned());
    tables.cust.extend(delta.cust.items.iter().cloned());
}

pub fn dump_page(msg: &Page, t: &Tables) -> String {
    let mut out = String::new();
    msg.dump(&mut out, t);
    out
}
